<?php

declare(strict_types=1);

namespace App\Support;

/**
 * The German banks by Bankleitzahl (docs/spec/07-mitglieder.md section 1):
 * name and BIC for a German IBAN, so the form fills in the BIC and shows
 * the bank, the import fills in missing BICs, and a BIC that does not fit
 * the IBAN gives a hint. Only German IBANs: the BLZ is digits 5-12.
 *
 * The data is app/data/banken.php, generated by tools/banken-erzeugen.php
 * from the Bundesbank's Bankleitzahlendatei (docs/betrieb.md, "Bankdaten
 * aktualisieren"). Loaded once per request, only when asked.
 */
final class Banken
{
    private const string DATEI = __DIR__ . '/../../data/banken.php';

    /** @var array<int|string, array{0: string, 1: string|null}>|null */
    private static ?array $daten = null;

    public static function fuerBlz(string $blz): ?Bank
    {
        if (preg_match('/^[1-9]\d{7}$/D', $blz) !== 1) {
            return null;
        }
        self::$daten ??= require self::DATEI;
        $eintrag = self::$daten[$blz] ?? null;

        return $eintrag === null ? null : new Bank($blz, $eintrag[0], $eintrag[1]);
    }

    /** The bank of a valid German IBAN; null for any other IBAN and an unknown BLZ. */
    public static function fuerIban(string $iban): ?Bank
    {
        $iban = Iban::normalisieren($iban);
        if (!str_starts_with($iban, 'DE') || !Iban::istGueltig($iban)) {
            return null;
        }

        return self::fuerBlz(substr($iban, 4, 8));
    }

    /**
     * Whether the BIC belongs to the IBAN: null when that cannot be told
     * (no valid German IBAN, unknown bank, bank without BIC, empty BIC).
     */
    public static function bicPasst(string $bic, string $iban): ?bool
    {
        $bank = self::fuerIban($iban);
        if ($bank?->bic === null || Bic::normalisieren($bic) === '') {
            return null;
        }

        return Bic::gleich($bic, $bank->bic);
    }

    /**
     * The BIC to save: the one given (normalised), or - when it is empty -
     * the BIC of the bank of a valid German IBAN, otherwise ''.
     */
    public static function bicErgaenzen(string $bic, string $iban): string
    {
        $bic = Bic::normalisieren($bic);

        return $bic !== '' ? $bic : (self::fuerIban($iban)?->bic ?? '');
    }
}
